I made a rect-based heatmap that maps var_a to x, var_b to y, and corr to a diverging color scale spanning -1 to 1, with tooltips showing the correlation to two decimals. Replace "correlations.csv" with your CSV path or URL.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "width": 400,
  "height": 400,
  "data": {
    "url": "correlations.csv",
    "format": {
      "type": "csv"
    }
  },
  "mark": {
    "type": "rect"
  },
  "encoding": {
    "x": {
      "field": "var_a",
      "type": "nominal",
      "axis": {
        "title": null,
        "labelAngle": -45
      }
    },
    "y": {
      "field": "var_b",
      "type": "nominal",
      "axis": {
        "title": null
      }
    },
    "color": {
      "field": "corr",
      "type": "quantitative",
      "scale": {
        "domain": [
          -1,
          0,
          1
        ],
        "range": [
          "#b2182b",
          "#f7f7f7",
          "#2166ac"
        ]
      },
      "legend": {
        "title": "Correlation"
      }
    },
    "tooltip": [
      {
        "field": "var_a",
        "type": "nominal",
        "title": "Var A"
      },
      {
        "field": "var_b",
        "type": "nominal",
        "title": "Var B"
      },
      {
        "field": "corr",
        "type": "quantitative",
        "title": "Corr",
        "format": ".2f"
      }
    ]
  }
}
```

